import{_ as a,C as s,o as d,c as n,a2 as t,E as r}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Product Barcode","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-barcode.md","filePath":"catalog/product-barcode.md","lastUpdated":1789411447000}'),c={name:"catalog/product-barcode.md"};function l(i,o,u,g,p,h){const e=s("ImagePopup");return d(),n("div",null,[o[0]||(o[0]=t('<h1 id="product-barcode" tabindex="-1">Product Barcode <a class="header-anchor" href="#product-barcode" aria-label="Permalink to &quot;Product Barcode&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>Every product can have a barcode for scanning when you pick, pack or count stock. You set the value, and the barcode image is created for you. You can also create and print barcodes for many products at once.</p><h2 id="add-a-barcode-to-a-product" tabindex="-1">Add a barcode to a product <a class="header-anchor" href="#add-a-barcode-to-a-product" aria-label="Permalink to &quot;Add a barcode to a product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Click the edit arrow on the product.</li><li>Open the <strong>Barcode</strong> step.</li><li>Enter the <strong>Barcode Value</strong>, such as the product code or GTIN you already use.</li><li>Click <strong>Save Product</strong>, or <strong>Submit</strong> for a draft.</li></ol>',5)),r(e,{src:"/images/product-barcode/barcode-tab.png",alt:"The Barcode step with a generated barcode"}),o[1]||(o[1]=t('<p>The <strong>Barcode</strong> image is created when you save and updated whenever the value changes. Click <strong>Download Barcode</strong> for a PDF of it. No two products can have the same barcode value.</p><p>The barcode uses <strong>Code 128</strong> unless you create it with another format from the products list.</p><h2 id="create-barcodes-for-many-products" tabindex="-1">Create barcodes for many products <a class="header-anchor" href="#create-barcodes-for-many-products" aria-label="Permalink to &quot;Create barcodes for many products&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Tick the products.</li><li>Click <strong>Select Action</strong>, point to <strong>Generate Barcode</strong> and choose <strong>Code 128</strong>, <strong>EAN-13</strong> or <strong>UPC-A</strong>.</li></ol><p>The message tells you how many barcodes were created and how many were skipped.</p><ul><li>A product without a barcode value gets a 12-digit value made from its catalog product ID, which isn&#39;t always the ID shown in the products list.</li><li>For <strong>EAN-13</strong> and <strong>UPC-A</strong>, a value that isn&#39;t a valid code of that kind is adjusted to one and saved.</li></ul><h2 id="print-barcodes" tabindex="-1">Print barcodes <a class="header-anchor" href="#print-barcodes" aria-label="Permalink to &quot;Print barcodes&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Tick the products.</li><li>Click <strong>Select Action &gt;&gt; Print Barcodes</strong>.</li></ol>',8)),r(e,{src:"/images/product-barcode/products-list.png",alt:"Generated barcodes in the products list with the Select Action menu"}),o[2]||(o[2]=t('<p>You get one PDF listing each product&#39;s <strong>ID</strong>, <strong>Name</strong> and <strong>Barcode</strong>, ready to print on labels. Products without a barcode value are left out.</p><h2 id="barcodes-in-the-products-list" tabindex="-1">Barcodes in the products list <a class="header-anchor" href="#barcodes-in-the-products-list" aria-label="Permalink to &quot;Barcodes in the products list&quot;">​</a></h2><p>The <strong>Barcode</strong> column shows each product&#39;s barcode and its value, or <strong>Not Generated</strong>. Use <strong>Filter</strong> to find a product by <strong>Barcode Value</strong>.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>A barcode on a catalog product you sell as your own is saved on the catalog product itself, so other sellers of that product see it too.</li><li>Team members need <strong>Product Barcode</strong> in their role, with <strong>Generate</strong> to create barcodes, and <strong>Print</strong> to print them or use <strong>Download Barcode</strong>.</li></ul>',5))])}const _=a(c,[["render",l]]);export{m as __pageData,_ as default};
